    p.add_argument("--format", choices=("csv",), default="csv")
    p.set_defaults(func=_cmd_export)

    p = sub.add_parser("add", help="append an entry", description="append an entry")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    p.set_defaults(func=_cmd_add)
    return parser


def _preprocess(argv):
    """Let option values start with a dash (``--category -x``) and keep ``add``
    arguments out of the option parser. Returns ``(argv, add_args)``."""
    argv = list(argv)
    index = next((i for i, a in enumerate(argv) if not a.startswith("-")), None)
    if index is None:
        return argv, None
    if argv[index] == "add":
        tail = argv[index + 1:]
        if tail and tail[0] in ("-h", "--help"):
            return argv, None
        return argv, tail
    out = argv[: index + 1]
    tail = argv[index + 1:]
    i = 0
    while i < len(tail):
        arg = tail[i]
        if arg == "--":
            out.extend(tail[i:])
            break
        if (
            arg in _VALUE_OPTIONS
            and i + 1 < len(tail)
            and tail[i + 1].startswith("-")
            and tail[i + 1] not in _KNOWN_OPTIONS
            and tail[i + 1] != "--"
        ):
            out.append(arg + "=" + tail[i + 1])
            i += 2
            continue
        out.append(arg)
        i += 1
    return out, None


def _read_ledger(path):
    try:
        if path == "-":
            stream = sys.stdin
            if stream is None:
                raise _InputError("cannot read standard input")
            buffer = getattr(stream, "buffer", None)
            data = buffer.read() if buffer is not None else stream.read()
            name = "standard input"
        else:
            with open(path, "rb") as handle:
                data = handle.read()
            name = path
        if isinstance(data, bytes):
            try:
                data = data.decode("utf-8-sig")
            except UnicodeDecodeError as exc:
                raise _InputError("cannot read %s: not valid UTF-8 (%s)" % (name, exc))
        elif data.startswith("\ufeff"):
            data = data[1:]
        return ledger.parse(data)
    except (OSError, ValueError) as exc:
        if isinstance(exc, (ParseError, _InputError)):
            raise
        raise _InputError(
            "cannot read %s: %s" % (path if path != "-" else "standard input", exc)
        )


def _sorted_entries(args):
    entries = _read_ledger(args.file)
    return sorted(entries, key=lambda e: e.date)


def _json(value):
    return json.dumps(value) + "\n"


def _totals_lines(totals):
    return [(k, ledger.format_amount(totals[k])) for k in sorted(totals)]


def _cmd_balance(args):
    total = ledger.format_amount(ledger.balance(_read_ledger(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _read_ledger(args.file)
    group = ledger.by_month if args.by == "month" else ledger.by_category
    rows = _totals_lines(group(entries))
    if args.json:
        return _json(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = ledger.filter_entries(
        _read_ledger(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = sorted(entries, key=lambda e: e.date)
    if args.json:
        return _json([_entry_dict(e) for e in entries])
    return "".join(ledger.format_entry(e) + "\n" for e in entries)


def _entry_dict(entry):
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": ledger.format_amount(entry.amount),
        "note": entry.note,
    }


def _cmd_export(args):
    entries = _sorted_entries(args)
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return buffer.getvalue()


def _cmd_add(args):
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise ParseError(1, "invalid %s %s" % (label, ledger._shorten(value)))
    candidate = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note.strip():
        candidate += " " + args.note
    if len(candidate.splitlines()) != 1:
        raise ParseError(1, "entry must be a single line")
    entries = ledger.parse(candidate)
    if len(entries) != 1:  # e.g. a date starting with '#'
        raise ParseError(1, "invalid entry %s" % ledger._shorten(candidate))
    line = ledger.format_entry(entries[0])

    prefix = b""
    try:
        with open(args.file, "rb") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell() > 0:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise _InputError("cannot read %s: %s" % (args.file, exc))
    try:
        with open(args.file, "ab") as handle:
            handle.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _InputError("cannot write %s: %s" % (args.file, exc))
    return line + "\n"


def _silence_stdout():
    """After a failed write, make sure the exit-time flush cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return 0
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 2
    except (OSError, ValueError) as exc:
        _silence_stdout()
        print("pennywise: cannot write output: %s" % exc, file=sys.stderr)
        return 2
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    parser = _build_parser()
    argv, add_args = _preprocess(argv)
    if add_args is not None:
        if not 4 <= len(add_args) <= 5:
            parser.error("add takes FILE DATE CATEGORY AMOUNT [NOTE]")
        names = ("file", "date", "category", "amount", "note")
        args = argparse.Namespace(command="add", func=_cmd_add, note="")
        for name, value in zip(names, add_args):
            setattr(args, name, value)
    else:
        args = parser.parse_args(argv)
    try:
        output = args.func(args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _InputError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    return _emit(output)


if __name__ == "__main__":
    sys.exit(main())
